parameters.query:
with target as (
  select id from agent_runs where clickup_task_id = $1 order by id desc limit 1
), upd as (
  update agent_runs set clickup_comment_id = $2, run_payload_bytes = $3, n8n_execution_id = $4
  where id = (select id from target)
  returning id
)
select (select id from target) as target_id, (select count(*) from upd)::int as updated;

