const wc = $('When Called').first().json;
let ops = wc.rendered_delta;
if (typeof ops === 'string') { try { ops = JSON.parse(ops || '[]'); } catch (e) { ops = []; } }
if (!Array.isArray(ops)) ops = [];
const agg = $('Aggregate Uploads').first().json;
const map = agg.upload_map || {};
const out = [];
const reviewer = Number(wc.reviewer_user_id);
